def evaluate(current_reputation, observation, my_history, round_num):
    # Gradual reputation update based on observed action
    if observation['action'] == 'cooperate':
        # Move reputation towards 1.0
        delta = (1.0 - current_reputation) * 0.2
    else:
        # Move reputation towards -1.0, with leniency in early rounds
        base = (current_reputation + 1.0) * 0.4
        if round_num < 10:
            delta = -base * 0.5
        else:
            delta = -base
    new_reputation = current_reputation + delta
    # Clamp to [-1.0, 1.0]
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    # Dynamic threshold: starts high and decreases slowly
    threshold = 0.8 - 0.003 * round_num
    # Be more trusting early in the game (few personal experiences)
    if len(my_history) < 5:
        threshold = max(threshold, 0.3)  # lower threshold means easier to cooperate
    return recipient_reputation > threshold
