def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation with a moving average: weight new observation more heavily
    alpha = 0.7  # learning rate
    if observation['action'] == 'cooperate':
        target = 0.8
    else:
        # Defection punishment increases gradually with rounds
        target = -0.8 - 0.2 * min(round_num / 10.0, 1.0)
    new_rep = (1 - alpha) * current_reputation + alpha * target
    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
    # Base threshold: starts high, decreases slowly over rounds
    base_threshold = max(0.2, 0.9 - 0.015 * round_num)
    # Adjust threshold based on own past behaviour (avoid using partner actions)
    if len(my_history) > 0:
        defections = 0
        for _, act in my_history:
            # Assume action is bool (True=cooperate, False=defect)
            # but also handle string format for safety
            if act is False or (isinstance(act, str) and act == 'defect'):
                defections += 1
        cooperations = len(my_history) - defections
        # If we have defected more often, become more lenient (lower threshold)
        if defections > cooperations:
            base_threshold *= 0.9
    return recipient_reputation > base_threshold
